# Getting Started with Android Development

Android powers over 70% of smartphones worldwide. This guide will help you start building Android apps using modern tools and best practices.

## Why Android Development?

- **Massive Market**: 2.5+ billion active Android devices
- **Career Opportunities**: High demand for Android developers
- **Open Source**: Android is open and customizable
- **Modern Tools**: Kotlin and Jetpack Compose make development easier

## Setting Up Your Environment

### Install Android Studio

1. Download from [developer.android.com](https://developer.android.com/studio)
2. Install Android Studio
3. Follow setup wizard
4. Install Android SDK and emulator

### Your First "Hello World" App

```kotlin
package com.example.myfirstapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MyFirstAppTheme {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    Greeting("Android")
                }
            }
        }
    }
}

@Composable
fun Greeting(name: String) {
    Text(
        text = "Hello $name!",
        style = MaterialTheme.typography.headlineMedium
    )
}
```

## Kotlin Basics for Android

### Variables and Data Types

```kotlin
// Variables
val name = "John"        // Immutable (can't change)
var age = 25             // Mutable (can change)

// Data types
val number: Int = 42
val price: Double = 9.99
val isStudent: Boolean = true
val letter: Char = 'A'
val text: String = "Hello"

// Null safety
var nullableString: String? = null  // Can be null
var nonNullString: String = "Text"  // Cannot be null
```

### Functions

```kotlin
// Simple function
fun greet(name: String): String {
    return "Hello, $name!"
}

// Single expression function
fun add(a: Int, b: Int) = a + b

// Default parameters
fun createUser(name: String, age: Int = 18) {
    println("User: $name, Age: $age")
}

// Usage
val message = greet("Alice")
val sum = add(5, 3)
createUser("Bob")  // Uses default age of 18
```

### Data Classes

```kotlin
data class User(
    val id: Int,
    val name: String,
    val email: String
)

// Usage
val user = User(1, "John", "john@example.com")
println(user.name)  // Access properties
val copy = user.copy(email = "new@example.com")  // Create copy
```

### Collections

```kotlin
// Lists
val numbers = listOf(1, 2, 3, 4, 5)
val mutableList = mutableListOf("A", "B", "C")
mutableList.add("D")

// Maps
val userScores = mapOf(
    "Alice" to 95,
    "Bob" to 87,
    "Charlie" to 92
)

// Filter, map operations
val evenNumbers = numbers.filter { it % 2 == 0 }
val doubled = numbers.map { it * 2 }
```

## Jetpack Compose Basics

### Composable Functions

```kotlin
@Composable
fun UserCard(name: String, email: String) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp)
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Text(
                text = name,
                style = MaterialTheme.typography.headlineSmall
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = email,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.secondary
            )
        }
    }
}
```

### State Management

```kotlin
@Composable
fun Counter() {
    // State that triggers recomposition
    var count by remember { mutableStateOf(0) }

    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Text(
            text = "Count: $count",
            style = MaterialTheme.typography.headlineMedium
        )

        Spacer(modifier = Modifier.height(16.dp))

        Button(onClick = { count++ }) {
            Text("Increment")
        }

        Spacer(modifier = Modifier.height(8.dp))

        Button(onClick = { count-- }) {
            Text("Decrement")
        }
    }
}
```

### Lists

```kotlin
