}
```

## Building a Complete App: Todo List

```kotlin
data class Todo(
    val id: Int,
    val text: String,
    var isCompleted: Boolean = false
)

@Composable
fun TodoApp() {
    var todos by remember {
        mutableStateOf(
            listOf(
                Todo(1, "Learn Kotlin"),
                Todo(2, "Build Android app")
            )
        )
    }

    var newTodoText by remember { mutableStateOf("") }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        // Title
        Text(
            text = "My Todos",
            style = MaterialTheme.typography.headlineLarge,
            modifier = Modifier.padding(bottom = 16.dp)
        )

        // Add new todo
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            OutlinedTextField(
                value = newTodoText,
                onValueChange = { newTodoText = it },
                label = { Text("New Todo") },
                modifier = Modifier.weight(1f)
            )

            Spacer(modifier = Modifier.width(8.dp))

            Button(
                onClick = {
                    if (newTodoText.isNotBlank()) {
                        todos = todos + Todo(
                            id = todos.size + 1,
                            text = newTodoText
                        )
                        newTodoText = ""
                    }
                }
            ) {
                Text("Add")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Todo list
        LazyColumn {
            items(todos) { todo ->
                TodoItemCard(
                    todo = todo,
                    onToggle = {
                        todos = todos.map {
                            if (it.id == todo.id) {
                                it.copy(isCompleted = !it.isCompleted)
                            } else it
                        }
                    },
                    onDelete = {
                        todos = todos.filter { it.id != todo.id }
                    }
                )
            }
        }
    }
}

@Composable
fun TodoItemCard(
    todo: Todo,
    onToggle: () -> Unit,
    onDelete: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (todo.isCompleted)
                MaterialTheme.colorScheme.surfaceVariant
            else
                MaterialTheme.colorScheme.surface
        )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Checkbox(
                checked = todo.isCompleted,
                onCheckedChange = { onToggle() }
            )

            Text(
                text = todo.text,
                modifier = Modifier.weight(1f),
                style = if (todo.isCompleted)
                    MaterialTheme.typography.bodyLarge.copy(
                        textDecoration = TextDecoration.LineThrough
                    )
                else
                    MaterialTheme.typography.bodyLarge
            )

            IconButton(onClick = onDelete) {
                Icon(
                    imageVector = Icons.Default.Delete,
                    contentDescription = "Delete"
                )
            }
        }
    }
}
```

## Navigation

```kotlin
// Add dependency in build.gradle
// implementation("androidx.navigation:navigation-compose:2.7.5")

sealed class Screen(val route: String) {
    object Home : Screen("home")
    object Profile : Screen("profile")
    object Settings : Screen("settings")
}

@Composable
fun Navigation() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = Screen.Home.route
    ) {
        composable(Screen.Home.route) {
            HomeScreen(navController)
        }
        composable(Screen.Profile.route) {
            ProfileScreen(navController)
        }
        composable(Screen.Settings.route) {
            SettingsScreen(navController)
        }
    }
}

// Navigate between screens
Button(onClick = {
    navController.navigate(Screen.Profile.route)
}) {
    Text("Go to Profile")
}
```

## Best Practices

1. ✅ **Use Kotlin** - Modern, concise, safe
2. ✅ **Follow Material Design** - Consistent UI/UX
3. ✅ **State management** - Keep UI in sync with data
4. ✅ **Handle lifecycle** - Save state across configuration changes
5. ✅ **Test on real devices** - Emulators are not enough
6. ✅ **Optimize performance** - Avoid unnecessary recompositions
7. ✅ **Follow naming conventions** - Clear, descriptive names

## Common Mistakes

❌ **Not using remember** - State will reset on recomposition
❌ **Ignoring null safety** - Use Kotlin's null safety features
❌ **Hardcoding strings** - Use string resources
❌ **Not testing on different devices** - Test various screen sizes
❌ **Blocking UI thread** - Use coroutines for async operations

